      black: "#000000",
      white: "#ffffff",
      background: withAlpha("background"),
      foreground: withAlpha("foreground"),
      "surface-1": withAlpha("surface-1"),
      card: { DEFAULT: withAlpha("card"), foreground: withAlpha("card-foreground"), raised: withAlpha("card-raised") },
